SELECT mp.photo_id AS photoId, mp.image_url AS imageUrl, mp.created_at AS createdAt, mp.liked AS heart, mp.editable AS editable, mp.user_list AS partnerEmails FROM my_photo mp WHERE mp.user_id = #{userId}
AND DATE(mp.created_at) >= #{cond.startDate}
AND DATE(mp.created_at) <= #{cond.endDate}
AND mp.liked = 1
AND mp.liked = 0
mp.user_list LIKE CONCAT('%', #{email}, '%')
AND mp.photo_id < #{cond.cursor}
ORDER BY mp.photo_id DESC LIMIT #{cond.limit}

